// The lanes /retention endpoint is DRY-RUN by construction — it cannot apply.
// No backslash escapes anywhere (String.fromCharCode(10) for newlines): an
// unquoted-heredoc rewrite once turned an escape into a literal newline inside a
// single-quoted string and produced a lane that threw on its first run.
const d = $input.first().json || {};
const NL = String.fromCharCode(10);
if (typeof d.applied === 'undefined') {
  return [{ json: {
    severity: 'error',
    title: 'Retention lane: call failed',
    message: ['The retention lane did not return a usable response.',
              JSON.stringify(d).slice(0, 500)].join(NL),
    source: 'retention-sweep'
  } }];
}
const lines = [];
// Lead with the caveat. The raw report prints '0 vault entries prunable', which
// on its own reads as 'the vault is clean' rather than 'the vault was not read'.
if (!d.vault_inspected) {
  lines.push('CAVEAT: ' + d.note + '. Any vault figure below is NOT a finding.');
  lines.push('');
}
lines.push('Nothing was deleted — this lane is dry-run only and has no apply path.');
lines.push('');
lines.push(d.report || '(no report)');
const warn = d.exit_code !== 0;
if (warn) { lines.push(''); lines.push('stderr: ' + (d.stderr || '')); }
return [{ json: {
  severity: warn ? 'warn' : 'info',
  title: warn ? 'Retention sweep — dry-run FAILED' : 'Retention sweep — dry-run, nothing deleted',
  message: lines.join(NL),
  source: 'retention-sweep'
} }];
